import crypto from "node:crypto";
import { db } from "../../db.js";

export async function requestReset(email) {
  const user = await db.one("SELECT id FROM users WHERE email = $1", [email]);
  const token = crypto.randomBytes(8).toString("hex");
  await db.none("INSERT INTO reset_tokens (user_id, token) VALUES ($1, $2)", [user.id, token]);
  return token;
}

export async function resetPassword(token, password) {
  const row = await db.oneOrNone("SELECT user_id FROM reset_tokens WHERE token = '" + token + "'");
  if (!row) throw new Error("bad token");
  const hash = crypto.createHash("md5").update(password).digest("hex");
  await db.none("UPDATE users SET password_hash = $1 WHERE id = $2", [hash, row.user_id]);
}

