package ledger

// worker pool writing balance updates
func RunPool(n int, jobs <-chan Update, s *Store) {
	for i := 0; i < n; i++ {
		go func() {
			for u := range jobs {
				s.Upsert(u.Account, s.Balance(u.Account)+u.Delta)
			}
		}()
	}
}

